1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"os"
8		"strconv"
9		"unicode/utf8"
10	)
11	
12	// EvalReason is the machine-readable outcome of a flag evaluation.
13	type EvalReason string
14	
15	const (
16		EvalDisabled EvalReason = "disabled"
17		EvalRule     EvalReason = "rule"
18		EvalDefault  EvalReason = "default"
19	)
20	
21	// Condition is one predicate over an evaluation context.
22	type Condition struct {
23		Attribute string
24		Op        string
25		// strVal 用于 eq；inVal 用于 in（至少一项）。
26		strVal string
27		inVal  []string
28	}
29	
30	// Rule groups conditions that must all hold; on match the flag takes Value.
31	type Rule struct {
32		ID         string
33		Value      bool
34		Conditions []Condition
35	}
36	
37	// Flag is one feature toggle with its default and ordered rules.
38	type Flag struct {
39		Key     string
40		Enabled bool
41		Default bool
42		Rules   []Rule
43	}
44	
45	// Config is a validated feature flag configuration.
46	type Config struct {
47		Flags []Flag
48	}
49	
50	// EvalResult is the deterministic outcome of evaluating one flag.
51	type EvalResult struct {
52		Key    string     `json:"key"`
53		Value  bool       `json:"value"`
54		Reason EvalReason `json:"reason"`
55		RuleID *string    `json:"ruleId"`
56	}
57	
58	// Equals reports whether two evaluation results are identical.
59	func (r EvalResult) Equals(other EvalResult) bool {
60		if r.Key != other.Key || r.Value != other.Value || r.Reason != other.Reason {
61			return false
62		}
63		if (r.RuleID == nil) != (other.RuleID == nil) {
64			return false
65		}
66		if r.RuleID != nil && *r.RuleID != *other.RuleID {
67			return false
68		}
69		return true
70	}
71	
72	// Context is a validated map of attribute names to string values.
73	type Context struct {
74		values map[string]string
75	}
76	
77	// LoadConfig reads and strictly validates a UTF-8 JSON flag config file.
78	// 所有开关都会被完整校验，包括不会被求值或已关闭的开关。
79	func LoadConfig(path string) (*Config, error) {
80		raw, err := os.ReadFile(path)
81		if err != nil {
82			return nil, fmt.Errorf("cannot read config file %q: %w", path, err)
83		}
84		return ParseConfig(raw)
85	}
86	
87	// LoadContext reads and validates a UTF-8 JSON context file.
88	func LoadContext(path string) (*Context, error) {
89		raw, err := os.ReadFile(path)
90		if err != nil {
91			return nil, fmt.Errorf("cannot read context file %q: %w", path, err)
92		}
93		return ParseContext(raw)
94	}
95	
96	// ParseConfig parses a config document from JSON bytes with strict typing.
97	// 先解析到 any 再逐字段校验，以区分“字段缺失”与“显式提供的 false”。
98	func ParseConfig(raw []byte) (*Config, error) {
99		if !utf8.Valid(raw) {
100			return nil, fmt.Errorf("config: file is not valid UTF-8")
101		}
102		if err := rejectInvalidUnicodeEscapes(raw, "config"); err != nil {
103			return nil, err
104		}
105		if err := rejectDuplicateFields(raw, "config"); err != nil {
106			return nil, err
107		}
108		var doc any
109		if err := json.Unmarshal(raw, &doc); err != nil {
110			return nil, fmt.Errorf("config: invalid JSON: %w", err)
111		}
112		root, ok := doc.(map[string]any)
113		if !ok {
114			return nil, fmt.Errorf("config: top level must be a JSON object")
115		}
116		flagsRaw, present := root["flags"]
117		if !present {
118			return nil, fmt.Errorf("config.flags: field is required")
119		}
120		if flagsRaw == nil {
121			return nil, fmt.Errorf("config.flags: must be an array, got null")
122		}
123		flagsArr, ok := flagsRaw.([]any)
124		if !ok {
125			return nil, fmt.Errorf("config.flags: must be an array")
126		}
127		cfg := &Config{}
128		seenKeys := map[string]int{}
129		for i, fr := range flagsArr {
130			flag, err := parseFlag(fr, i)
131			if err != nil {
132				return nil, err
133			}
134			if prev, dup := seenKeys[flag.Key]; dup {
135				return nil, fmt.Errorf("config.flags[%d].key: duplicate flag key %q (first at flags[%d])", i, flag.Key, prev)
136			}
137			seenKeys[flag.Key] = i
138			cfg.Flags = append(cfg.Flags, flag)
139		}
140		return cfg, nil
141	}
142	
143	// ParseContext parses an attribute-name -> string context object; it may be empty.
144	func ParseContext(raw []byte) (*Context, error) {
145		if !utf8.Valid(raw) {
146			return nil, fmt.Errorf("context: file is not valid UTF-8")
147		}
148		if err := rejectInvalidUnicodeEscapes(raw, "context"); err != nil {
149			return nil, err
150		}
151		if err := rejectDuplicateFields(raw, "context"); err != nil {
152			return nil, err
153		}
154		var doc any
155		if err := json.Unmarshal(raw, &doc); err != nil {
156			return nil, fmt.Errorf("context: invalid JSON: %w", err)
157		}
158		root, ok := doc.(map[string]any)
159		if !ok {
160			return nil, fmt.Errorf("context: top level must be a JSON object")
161		}
162		ctx := &Context{values: make(map[string]string, len(root))}
163		for k, v := range root {
164			s, ok := v.(string)
165			if !ok {
166				return nil, fmt.Errorf("context.%s: value must be a string", k)
167			}
168			ctx.values[k] = s
169		}
170		return ctx, nil
171	}
172	
173	// Get looks up an attribute; an empty string is a legal value.
174	func (c *Context) Get(attribute string) (string, bool) {
175		if c == nil {
176			return "", false
177		}
178		v, ok := c.values[attribute]
179		return v, ok
180	}
181	
182	// Find returns the flag with the given key, or nil if absent.
183	func (c *Config) Find(key string) *Flag {
184		if c == nil {
185			return nil
186		}
187		for i := range c.Flags {
188			if c.Flags[i].Key == key {
189				return &c.Flags[i]
190			}
191		}
192		return nil
193	}
194	
195	// Evaluate deterministically evaluates a flag against a context.
196	// 未启用固定 false（reason=disabled），不使用默认值或规则；启用后取首条
197	// 所有条件均成立的规则的 value；无匹配取 default。求值不依赖时间、随机数
198	// 或 map 遍历顺序，同一配置与上下文重复求值结果一致。
199	func (f *Flag) Evaluate(ctx *Context) EvalResult {
200		if !f.Enabled {
201			return EvalResult{Key: f.Key, Value: false, Reason: EvalDisabled, RuleID: nil}
202		}
203		for i := range f.Rules {
204			rule := &f.Rules[i]
205			if rule.matches(ctx) {
206				id := rule.ID
207				return EvalResult{Key: f.Key, Value: rule.Value, Reason: EvalRule, RuleID: &id}
208			}
209		}
210		return EvalResult{Key: f.Key, Value: f.Default, Reason: EvalDefault, RuleID: nil}
211	}
212	
213	func (r *Rule) matches(ctx *Context) bool {
214		for i := range r.Conditions {
215			if !r.Conditions[i].matches(ctx) {
216				return false
217			}
218		}
219		return true
220	}
221	
222	func (c Condition) matches(ctx *Context) bool {
223		v, present := ctx.Get(c.Attribute)
224		if !present {
225			return false
226		}
227		switch c.Op {
228		case "eq":
229			return v == c.strVal
230		case "in":
231			for _, candidate := range c.inVal {
232				if v == candidate {
233					return true
234				}
235			}
236			return false
237		default:
238			// 解析阶段已拒绝未知运算符，防御性处理。
239			return false
240		}
241	}
242	
243	// MarshalResult renders the result as a single compact JSON object.
244	func MarshalResult(r EvalResult) ([]byte, error) {
245		var buf bytes.Buffer
246		enc := json.NewEncoder(&buf)
247		enc.SetEscapeHTML(false)
248		if err := enc.Encode(r); err != nil {
249			return nil, err
250		}
251		return bytes.TrimRight(buf.Bytes(), "\n"), nil
252	}
253	
254	// --- strict parsing helpers -------------------------------------------------
255	
256	// rejectDuplicateFields 按文件原文顺序扫描 JSON 令牌流，拒绝任何在同一对象内
257	// 重复声明的字段名。字段名按解码后的字符串比较（"enabled" 与 "énabled"
258	// 同名），大小写不同仍是不同字段，名字中的空白不裁剪。检查覆盖所有对象，
259	// 包括附加字段里嵌套的对象；数组元素不属于这一检查。label 是根对象的位置
260	// 前缀（"config" 或 "context"）。JSON 语法错误不在此报告，留给 Unmarshal。
261	func rejectDuplicateFields(raw []byte, label string) error {
262		dec := json.NewDecoder(bytes.NewReader(raw))
263		type frame struct {
264			path      string
265			object    bool
266			keys      map[string]struct{}
267			lastKey   string
268			expectKey bool
269			nextIndex int
270		}
271		var stack []*frame
272		// valueDone 在栈顶容器完成一个值（对象的一个字段值或数组的一个元素）后调用。
273		valueDone := func() {
274			if len(stack) == 0 {
275				return
276			}
277			top := stack[len(stack)-1]
278			if top.object {
279				top.expectKey = true
280			} else {
281				top.nextIndex++
282			}
283		}
284		childPath := func() string {
285			top := stack[len(stack)-1]
286			if top.object {
287				return top.path + "." + top.lastKey
288			}
289			return top.path + "[" + strconv.Itoa(top.nextIndex) + "]"
290		}
291		for {
292			tok, err := dec.Token()
293			if err != nil {
294				// io.EOF 或语法错误；语法错误由后续 Unmarshal 报告。
295				break
296			}
297			switch t := tok.(type) {
298			case json.Delim:
299				switch t {
300				case '{', '[':
301					path := label
302					if len(stack) > 0 {
303						path = childPath()
304					}
305					f := &frame{path: path, object: t == '{', expectKey: true}
306					if f.object {
307						f.keys = make(map[string]struct{})
308					}
309					stack = append(stack, f)
310				case '}', ']':
311					stack = stack[:len(stack)-1]
312					valueDone()
313				}
314			case string:
315				if len(stack) > 0 && stack[len(stack)-1].object && stack[len(stack)-1].expectKey {
316					top := stack[len(stack)-1]
317					if _, dup := top.keys[t]; dup {
318						return fmt.Errorf("%s.%s: duplicate field %q", top.path, t, t)
319					}
320					top.keys[t] = struct{}{}
321					top.lastKey = t
322					top.expectKey = false
323				} else {
324					valueDone()
325				}
326			default:
327				valueDone()
328			}
329		}
330		return nil
331	}
332	
333	// rejectInvalidUnicodeEscapes 按文件原文顺序扫描 JSON 文本，拒绝任何不能组成
334	// 完整字符的 \uXXXX 转义：孤立的高代理项、孤立的低代理项，以及不完整或顺序
335	// 错误的代理项对。encoding/json 解码时会把这类转义静默替换为 U+FFFD，使非法
336	// 输入与真正的 "�" 被当作相同字符串参与求值，或让字段名在替换后被误判为重复，
337	// 因此必须在解码前按原文拒绝。检查覆盖字段名与所有字符串值（包括规则的比较值、
338	// in 列表元素以及附加字段里的字符串），一个文件有多个问题时报告原文中最先出现
339	// 的一处。label 是根对象的位置前缀（"config" 或 "context"）。JSON 语法错误
340	// 不在此报告，留给 Unmarshal。
341	func rejectInvalidUnicodeEscapes(raw []byte, label string) error {
342		type frame struct {
343			path      string
344			object    bool
345			lastKey   string
346			expectKey bool
347			nextIndex int
348		}
349		var stack []*frame
350		valueDone := func() {
351			if len(stack) == 0 {
352				return
353			}
354			top := stack[len(stack)-1]
355			if top.object {
356				top.expectKey = true
357			} else {
358				top.nextIndex++
359			}
360		}
361		childPath := func() string {
362			top := stack[len(stack)-1]
363			if top.object {
364				return top.path + "." + top.lastKey
365			}
366			return top.path + "[" + strconv.Itoa(top.nextIndex) + "]"
367		}
368		i := 0
369		for i < len(raw) {
370			c := raw[i]
371			switch {
372			case c == '{' || c == '[':
373				path := label
374				if len(stack) > 0 {
375					path = childPath()
376				}
377				stack = append(stack, &frame{path: path, object: c == '{', expectKey: c == '{'})
378				i++
379			case c == '}' || c == ']':
380				if len(stack) > 0 {
381					stack = stack[:len(stack)-1]
382				}
383				valueDone()
384				i++
385			case c == '"':
386				end := jsonStringEnd(raw, i)
387				contentEnd := end
388				if contentEnd > i+1 && raw[contentEnd-1] == '"' {
389					contentEnd-- // 去掉右引号；未终止的字符串留给 Unmarshal 报告
390				}
391				content := raw[i+1 : contentEnd]
392				if bad := findBadUnicodeEscape(content); bad != nil {
393					if len(stack) > 0 && stack[len(stack)-1].object && stack[len(stack)-1].expectKey {
394						top := stack[len(stack)-1]
395						return fmt.Errorf("%s: field name %q contains invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
396							top.path, string(content), bad.escape, bad.detail)
397					}
398					path := label
399					if len(stack) > 0 {
400						path = childPath()
401					}
402					return fmt.Errorf("%s: invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
403						path, bad.escape, bad.detail)
404				}
405				if len(stack) > 0 && stack[len(stack)-1].object && stack[len(stack)-1].expectKey {
406					top := stack[len(stack)-1]
407					var key string
408					// 转义已校验合法，解码用于定位路径；失败说明是语法错误，留给 Unmarshal。
409					if err := json.Unmarshal(raw[i:end], &key); err == nil {
410						top.lastKey = key
411					}
412					top.expectKey = false
413				} else {
414					valueDone()
415				}
416				i = end
417			case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == ':' || c == ',':
418				i++
419			default:
420				// 数字与 true/false/null 等标量：跳过至下一个结构字符，按一个值计。
421				for i < len(raw) && !isJSONStructural(raw[i]) {
422					i++
423				}
424				valueDone()
425			}
426		}
427		return nil
428	}
429	
430	// badEscape 描述一处不能组成完整字符的 \uXXXX 转义。
431	type badEscape struct {
432		escape string // 原文中的转义序列，如 \uD800
433		detail string // 具体问题（孤立高代理项/孤立低代理项）
434	}
435	
436	// jsonStringEnd 返回从 raw[i]（必须是 '"'）开始的字符串字面量结束位置
437	// （右引号之后的下标）；未终止时返回 len(raw)。
438	func jsonStringEnd(raw []byte, i int) int {
439		j := i + 1
440		for j < len(raw) {
441			switch raw[j] {
442			case '\\':
443				j += 2
444			case '"':
445				return j + 1
446			default:
447				j++
448			}
449		}
450		return len(raw)
451	}
452	
453	// findBadUnicodeEscape 在字符串内容（不含引号）中查找第一处不能组成完整
454	// 字符的 \uXXXX 转义；没有则返回 nil。反斜杠本身的转义（\\）先于 \u 判定，
455	// 因此 "\\uD800" 只是普通文本。非法的 \u 写法（非 4 位十六进制）属于 JSON
456	// 语法错误，不在此报告。
457	func findBadUnicodeEscape(content []byte) *badEscape {
458		j := 0
459		for j < len(content) {
460			if content[j] != '\\' {
461				j++
462				continue
463			}
464			if j+1 >= len(content) {
465				break
466			}
467			if content[j+1] != 'u' {
468				j += 2
469				continue
470			}
471			if j+6 > len(content) || !isHex4(content[j+2:j+6]) {
472				j += 2
473				continue
474			}
475			cp := hexVal4(content[j+2 : j+6])
476			switch {
477			case cp >= 0xD800 && cp <= 0xDBFF:
478				// 高代理项只有紧跟一个低代理项转义才组成完整字符。
479				if j+12 <= len(content) && content[j+6] == '\\' && content[j+7] == 'u' &&
480					isHex4(content[j+8:j+12]) {
481					if lo := hexVal4(content[j+8 : j+12]); lo >= 0xDC00 && lo <= 0xDFFF {
482						j += 12
483						continue
484					}
485				}
486				return &badEscape{
487					escape: string(content[j : j+6]),
488					detail: "high surrogate is not followed by a low surrogate",
489				}
490			case cp >= 0xDC00 && cp <= 0xDFFF:
491				return &badEscape{
492					escape: string(content[j : j+6]),
493					detail: "low surrogate is not preceded by a high surrogate",
494				}
495			}
496			j += 6
497		}
498		return nil
499	}
500	
501	// isJSONStructural 报告 b 是否为 JSON 结构字符或空白（标量值的边界）。
502	func isJSONStructural(b byte) bool {
503		switch b {
504		case ' ', '\t', '\n', '\r', '{', '}', '[', ']', ':', ',', '"':
505			return true
506		}
507		return false
508	}
509	
510	// isHex4 报告 b 是否恰好为 4 个十六进制数字。
511	func isHex4(b []byte) bool {
512		if len(b) != 4 {
513			return false
514		}
515		for _, c := range b {
516			if !isHexDigit(c) {
517				return false
518			}
519		}
520		return true
521	}
522	
523	func isHexDigit(c byte) bool {
524		return ('0' <= c && c <= '9') || ('a' <= c && c <= 'f') || ('A' <= c && c <= 'F')
525	}
526	
527	// hexVal4 把 4 个十六进制数字解析为码点值；调用前须先经 isHex4 校验。
528	func hexVal4(b []byte) int {
529		v := 0
530		for _, c := range b {
531			v <<= 4
532			switch {
533			case '0' <= c && c <= '9':
534				v |= int(c - '0')
535			case 'a' <= c && c <= 'f':
536				v |= int(c-'a') + 10
537			default: // 'A' <= c && c <= 'F'
538				v |= int(c-'A') + 10
539			}
540		}
541		return v
542	}
543	
544	func parseFlag(raw any, index int) (Flag, error) {
545		loc := fmt.Sprintf("config.flags[%d]", index)
546		obj, ok := raw.(map[string]any)
547		if !ok {
548			return Flag{}, fmt.Errorf("%s: flag must be a JSON object", loc)
549		}
550		key, err := requireNonEmptyString(obj, "key", loc)
551		if err != nil {
552			return Flag{}, err
553		}
554		enabled, err := requireBool(obj, "enabled", loc)
555		if err != nil {
556			return Flag{}, err
557		}
558		def, err := requireBool(obj, "default", loc)
559		if err != nil {
560			return Flag{}, err
561		}
562		rulesArr, err := requireArrayField(obj, "rules", loc)
563		if err != nil {
564			return Flag{}, err
565		}
566		flag := Flag{Key: key, Enabled: enabled, Default: def}
567		seenRules := map[string]int{}
568		for ri, rv := range rulesArr {
569			rule, err := parseRule(rv, index, ri)
570			if err != nil {
571				return Flag{}, err
572			}
573			if prev, dup := seenRules[rule.ID]; dup {
574				return Flag{}, fmt.Errorf("%s.rules[%d].id: duplicate rule id %q (first at rules[%d])", loc, ri, rule.ID, prev)
575			}
576			seenRules[rule.ID] = ri
577			flag.Rules = append(flag.Rules, rule)
578		}
579		return flag, nil
580	}
581	
582	func parseRule(raw any, flagIndex, ruleIndex int) (Rule, error) {
583		loc := fmt.Sprintf("config.flags[%d].rules[%d]", flagIndex, ruleIndex)
584		obj, ok := raw.(map[string]any)
585		if !ok {
586			return Rule{}, fmt.Errorf("%s: rule must be a JSON object", loc)
587		}
588		id, err := requireNonEmptyString(obj, "id", loc)
589		if err != nil {
590			return Rule{}, err
591		}
592		value, err := requireBool(obj, "value", loc)
593		if err != nil {
594			return Rule{}, err
595		}
596		condsArr, err := requireArrayField(obj, "conditions", loc)
597		if err != nil {
598			return Rule{}, err
599		}
600		if len(condsArr) == 0 {
601			return Rule{}, fmt.Errorf("%s.conditions: must contain at least one condition", loc)
602		}
603		rule := Rule{ID: id, Value: value}
604		for ci, cv := range condsArr {
605			cond, err := parseCondition(cv, flagIndex, ruleIndex, ci)
606			if err != nil {
607				return Rule{}, err
608			}
609			rule.Conditions = append(rule.Conditions, cond)
610		}
611		return rule, nil
612	}
613	
614	func parseCondition(raw any, flagIndex, ruleIndex, condIndex int) (Condition, error) {
615		loc := fmt.Sprintf("config.flags[%d].rules[%d].conditions[%d]", flagIndex, ruleIndex, condIndex)
616		obj, ok := raw.(map[string]any)
617		if !ok {
618			return Condition{}, fmt.Errorf("%s: condition must be a JSON object", loc)
619		}
620		attribute, err := requireNonEmptyString(obj, "attribute", loc)
621		if err != nil {
622			return Condition{}, err
623		}
624		op, err := requireNonEmptyString(obj, "op", loc)
625		if err != nil {
626			return Condition{}, err
627		}
628		valueField, err := requireField(obj, "value", loc)
629		if err != nil {
630			return Condition{}, err
631		}
632		cond := Condition{Attribute: attribute, Op: op}
633		switch op {
634		case "eq":
635			s, ok := valueField.(string)
636			if !ok {
637				return Condition{}, fmt.Errorf("%s.value: must be a string when op is %q", loc, op)
638			}
639			cond.strVal = s
640		case "in":
641			arr, ok := valueField.([]any)
642			if !ok {
643				return Condition{}, fmt.Errorf("%s.value: must be an array when op is %q", loc, op)
644			}
645			if len(arr) == 0 {
646				return Condition{}, fmt.Errorf("%s.value: in-list must contain at least one item", loc)
647			}
648			for ii, item := range arr {
649				s, ok := item.(string)
650				if !ok {
651					return Condition{}, fmt.Errorf("%s.value[%d]: must be a string", loc, ii)
652				}
653				cond.inVal = append(cond.inVal, s)
654			}
655		default:
656			return Condition{}, fmt.Errorf("%s.op: unknown operator %q (allowed: eq, in)", loc, op)
657		}
658		return cond, nil
659	}
660	
661	func requireField(obj map[string]any, name, loc string) (any, error) {
662		v, ok := obj[name]
663		if !ok {
664			return nil, fmt.Errorf("%s.%s: field is required", loc, name)
665		}
666		if v == nil {
667			return nil, fmt.Errorf("%s.%s: must not be null", loc, name)
668		}
669		return v, nil
670	}
671	
672	func requireArrayField(obj map[string]any, name, loc string) ([]any, error) {
673		v, err := requireField(obj, name, loc)
674		if err != nil {
675			return nil, err
676		}
677		arr, ok := v.([]any)
678		if !ok {
679			return nil, fmt.Errorf("%s.%s: must be an array", loc, name)
680		}
681		return arr, nil
682	}
683	
684	func requireNonEmptyString(obj map[string]any, name, loc string) (string, error) {
685		v, err := requireField(obj, name, loc)
686		if err != nil {
687			return "", err
688		}
689		s, ok := v.(string)
690		if !ok {
691			return "", fmt.Errorf("%s.%s: must be a string", loc, name)
692		}
693		if s == "" {
694			return "", fmt.Errorf("%s.%s: must not be empty", loc, name)
695		}
696		return s, nil
697	}
698	
699	func requireBool(obj map[string]any, name, loc string) (bool, error) {
700		v, err := requireField(obj, name, loc)
701		if err != nil {
702			return false, err
703		}
704		b, ok := v.(bool)
705		if !ok {
706			return false, fmt.Errorf("%s.%s: must be a boolean", loc, name)
707		}
708		return b, nil
709	}
