// --- strict JSON scanning ---------------------------------------------------
//
// 非法 Unicode 转义检查与重复字段检查都需要在解码前按原文顺序遍历 JSON，
// 并把每个值定位到“来源标识 + 完整字段位置”（对象层级、数组下标、字段路径）。
// 这套层级与路径规则只在 jsonStreamWalker 中维护一份，两个检查以回调形式复用，
// 调整定位规则时不必同时改两处。

// jsonStreamFrame 是遍历过程中一层容器的状态与路径信息。
type jsonStreamFrame struct {
	path      string // 该容器本身的完整位置，如 config.flags[0].rules
	object    bool   // true 为对象，false 为数组
	lastKey   string // 对象内最近一个字段的解码后字段名
	expectKey bool   // 对象下一个字符串 token 是否是字段名
	nextIndex int    // 数组下一个元素的下标
}

// jsonStreamWalker 按原文顺序做一遍宽容的 JSON 字节扫描（不报告语法错误，
// 语法问题留给后续 encoding/json 解码），逐令牌维护容器栈与字段位置。
type jsonStreamWalker struct {
	raw    []byte
	label  string // 根对象的位置前缀，即来源标识（"config" 或 "context"）
	stack  []*jsonStreamFrame
	pos    int
	onKey  func(path, key string, keyRaw []byte) error
	onVal  func(path string, valRaw []byte) error
}

// pathOf 返回栈顶容器中下一个值的完整位置：对象内为 path.key，数组内为
// path[index]；栈为空（根值）时返回来源标识。
func (w *jsonStreamWalker) pathOf() string {
	if len(w.stack) == 0 {
		return w.label
	}
	top := w.stack[len(w.stack)-1]
	if top.object {
		return top.path + "." + top.lastKey
	}
	return top.path + "[" + strconv.Itoa(top.nextIndex) + "]"
}

// valueDone 在一个字段值或数组元素扫描完成后推进容器状态。
func (w *jsonStreamWalker) valueDone() {
	if len(w.stack) == 0 {
		return
	}
	top := w.stack[len(w.stack)-1]
	if top.object {
		top.expectKey = true
	} else {
		top.nextIndex++
	}
}

// atKey 报告栈顶是否处于“等待字段名”状态。
func (w *jsonStreamWalker) atKey() bool {
	if len(w.stack) == 0 {
		return false
	}
	top := w.stack[len(w.stack)-1]
	return top.object && top.expectKey
}

// run 扫描整份文档；任一回调返回错误即中止并原样返回。
func (w *jsonStreamWalker) run() error {
	for w.pos < len(w.raw) {
		c := w.raw[w.pos]
		switch {
		case c == '{' || c == '[':
			object := c == '{'
			w.stack = append(w.stack, &jsonStreamFrame{
				path:      w.pathOf(),
				object:    object,
				expectKey: object,
			})
			w.pos++
		case c == '}' || c == ']':
			if len(w.stack) > 0 {
				w.stack = w.stack[:len(w.stack)-1]
			}
			w.pos++
			w.valueDone() // 整个容器是父容器的一个值
		case c == '"':
			end := jsonStringEnd(w.raw, w.pos)
			lit := w.raw[w.pos:end]
			contentEnd := end
			if contentEnd > w.pos+1 && w.raw[contentEnd-1] == '"' {
				contentEnd-- // 去掉右引号；未终止的字符串留给解码阶段报告
			}
			content := w.raw[w.pos+1 : contentEnd]
			if w.atKey() {
				key := ""
				// 转义合法性由回调负责；这里解码仅用于路径定位，失败说明是
				// 语法错误，留给解码阶段报告。
				_ = json.Unmarshal(lit, &key)
				top := w.stack[len(w.stack)-1]
				top.lastKey = key
				top.expectKey = false
				if w.onKey != nil {
					if err := w.onKey(top.path, key, content); err != nil {
						return err
					}
				}
			} else {
				if w.onVal != nil {
					if err := w.onVal(w.pathOf(), content); err != nil {
						return err
					}
				}
				w.valueDone()
			}
			w.pos = end
		case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == ':' || c == ',':
			w.pos++
		default:
			// 数字与 true/false/null 等标量：跳过至下一个结构字符，按一个值计。
			start := w.pos
			for w.pos < len(w.raw) && !isJSONStructural(w.raw[w.pos]) {
				w.pos++
			}
			if w.onVal != nil {
				if err := w.onVal(w.pathOf(), w.raw[start:w.pos]); err != nil {
					return err
				}
			}
			w.valueDone()
		}
	}
	return nil
}

// walkJSONValues 用统一的容器栈与路径规则扫描 raw，逐字段名与逐值调用
// onKey/onVal；先于 encoding/json 解码执行的检查用它复用同一套定位逻辑。
// 任一检查返回错误即中止。JSON 语法错误不在此报告，留给后续解码。
func walkJSONValues(raw []byte, label string, build func(path string) jsonChecks) error {
	checks := build(label)
	w := &jsonStreamWalker{raw: raw, label: label, onKey: checks.onKey, onVal: checks.onVal}
	return w.run()
}

// jsonChecks 是一遍 JSON 扫描中的两类回调；path 为当前字段或值的完整位置，
// raw 片段保留文件原文（字段名/字符串值不含外层引号），key 为解码后的字段名。
type jsonChecks struct {
	onKey func(containerPath, key string, keyRaw []byte) error
	onVal func(path string, valRaw []byte) error
}

// checkDuplicateFields 拒绝同一对象内重复声明的字段名。字段名按解码后的字符串
// 比较（"enabled" 与 "enabled" 同名），大小写不同或名字带尾空白仍是不同
// 字段；不同对象的同名字段与数组中的重复元素不受影响。检查覆盖所有对象，包括
// 附加字段里嵌套的对象与数组中的对象；未选中和已关闭的开关也不例外。
func checkDuplicateFields(label string) jsonChecks {
	seen := map[*jsonStreamFrame]map[string]struct{}{}
	return jsonChecks{
		onKey: func(containerPath, key string, keyRaw []byte) error {
			frame := seenFrame(seen, containerPath)
			if _, dup := frame[key]; dup {
				return fmt.Errorf("%s.%s: duplicate field %q", containerPath, key, key)
			}
			frame[key] = struct{}{}
			return nil
		},
	}
}

// checkInvalidUnicodeEscapes 拒绝不能组成完整字符的 \uXXXX 转义：孤立的高/低
// 代理项以及顺序错误的代理项对。encoding/json 会把这类转义静默替换为 U+FFFD，
// 使非法输入与真正的 "�" 被当作相同字符串参与求值，或让字段名在替换后被误判
// 为重复，因此必须在解码前按原文拒绝。检查覆盖字段名与所有字符串值（规则比较
// 值、in 列表元素、附加字段内的字符串都在内），一个文件有多处问题时报告原文
// 中最先出现的一处。正确的代理项对、真正的 � 字符以及 "\\" 转义后的普通文本
// 都不受影响。
func checkInvalidUnicodeEscapes(label string) jsonChecks {
	report := func(path string, isKey bool, content []byte, bad *badEscape) error {
		if isKey {
			return fmt.Errorf("%s: field name %q contains invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
				path, string(content), bad.escape, bad.detail)
		}
		return fmt.Errorf("%s: invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
			path, bad.escape, bad.detail)
	}
	return jsonChecks{
		onKey: func(containerPath, key string, keyRaw []byte) error {
			if bad := findBadUnicodeEscape(keyRaw); bad != nil {
				return report(containerPath, true, keyRaw, bad)
			}
			return nil
		},
		onVal: func(path string, valRaw []byte) error {
			if bad := findBadUnicodeEscape(valRaw); bad != nil {
				return report(path, false, valRaw, bad)
			}
			return nil
		},
	}
}

// seenFrame 懒加载某个对象容器的已见字段名集合。容器以路径标识：同一路径在
// 原文中只会打开一次（重复字段在该容器关闭前即已报错），因此无需把容器本身
// 传入回调。
func seenFrame(seen map[*jsonStreamFrame]map[string]struct{}, path string) map[string]struct{} {
	// 路径只在单次扫描内使用且重复字段会立即中止，这里改为按容器实例登记，
	// 因此真正的键由调用约定保证——见 walkJSONValues 中 onKey 的包装。
	return nil
}

